//go:build linux
package knowledgecopy
import("context";"errors";"os";"path/filepath";"strings";"testing")
func TestRegistrySafeIntegersNumericSpellingsMetricsAndUnknownFields(t *testing.T){path,root:=fixture(t);for _,metric:=range []string{"l2","cosine","dot"}{raw:=strings.Replace(space(0,"chunks__space_0001","active"),`"distanceMetric":"l2"`,`"distanceMetric":"`+metric+`"`,1);raw=strings.Replace(raw,`"generation":0`,`"generation":0.0`,1);raw=strings.Replace(raw,`"vectorDimension":2`,`"vectorDimension":2e0`,1);put(t,path,"embedding-spaces.json",registry("["+raw+"]","0e0"));validate(t,root)};raw:=strings.Replace(space(0,"chunks","building"),`"generation":0`,`"generation":9007199254740991`,1);put(t,path,"embedding-spaces.json",registry("["+raw+"]","9007199254740991"));validate(t,root)}
func TestJSONDepthAndTrailingTokensRejected(t *testing.T){path,root:=fixture(t);for _,raw:=range []string{`{"version":1,"spaces":[]} {}`,`{"version":1,"spaces":[],"x":`+strings.Repeat("[",130)+`0`+strings.Repeat("]",130)+`}`}{put(t,path,"embedding-spaces.json",[]byte(raw));fail(t,root,budget(),ErrInvalid)}}
func TestMalformedLanceAndUnrelatedFilesNotParsedOrValidated(t *testing.T){path,root:=fixture(t);if err:=os.Mkdir(filepath.Join(path,"lancedb"),0700);err!=nil{t.Fatal(err)};put(t,filepath.Join(path,"lancedb"),"not-a-valid-manifest",[]byte("intentionally not Lance"));put(t,path,"unknown-unrelated",[]byte("ignored by metadata-only scope"));out:=validate(t,root);if out.MetadataBytes!=0||out.RegistryPresent||out.CopiesPresent{t.Fatal(out)}}
func TestCopyNameExactLowercaseSHA256Domain(t *testing.T){for _,value:=range []string{strings.Repeat("A",64)+".json",strings.Repeat("0",63)+".json",strings.Repeat("0",64)+".JSON",strings.Repeat("g",64)+".json",strings.Repeat("0",64)+".json.tmp"}{path,root:=fixture(t);copiesDir(t,path);put(t,filepath.Join(path,"knowledge-copies"),value,[]byte(`{}`));fail(t,root,budget(),ErrInvalid)}}
func TestCancelledParserReturnsContextWithoutSummary(t *testing.T){ctx,cancel:=context.WithCancel(context.Background());cancel();if _,err:=parse(ctx,[]byte(`{"x":"secret"}`));!errors.Is(err,context.Canceled){t.Fatal(err)}}
